import math
L=2.75
X=0.0;Y=0.0;TH=0.0
walls={}
clusters=[]
tgt=None
phase='rev';fwd_dist=0.0;last_touch=0;stuck_t=0.0;prev_rel=0.0
tick=0
def clip(v,a,b):
    return a if v<a else (b if v>b else v)
def w2(px,py):
    c=math.cos(TH);s=math.sin(TH)
    return (X+c*px-s*py, Y+s*px+c*py)
def angn(a):
    return (a+math.pi)%(2*math.pi)-math.pi
def look_for(tk):
    m=tk%32
    if m<22: return -23.0
    if m<27: return -65.0
    if m<29: return -23.0
    return 43.0
def pts_of(lst):
    out=[]
    for it in lst or []:
        try:
            if isinstance(it,(list,tuple)) and len(it)>=2 and isinstance(it[0],(int,float)) and isinstance(it[1],(int,float)):
                out.append((float(it[0]),float(it[1])))
        except Exception:
            pass
    return out
def free_dir(R,a,hw):
    ux=math.cos(a);uy=math.sin(a)
    f=12.0
    for (px,py) in walls.values():
        rx=px-R[0];ry=py-R[1]
        al=rx*ux+ry*uy
        if al<0.3 or al>f: continue
        lat=abs(rx*uy-ry*ux)
        if lat<hw: f=al
    return f
def control(obs):
    global X,Y,TH,tgt,phase,fwd_dist,last_touch,stuck_t,prev_rel,tick
    tick+=1
    try:
        return _control(obs)
    except Exception as e:
        if tick%20==0: print('ERR',e)
        return (0.0,-0.6,-23.0)
def _control(obs):
    global X,Y,TH,tgt,phase,fwd_dist,last_touch,stuck_t,prev_rel,tick
    dt=obs.get('dt',0.1) or 0.1
    mo=obs.get('motion',{})
    v=mo.get('v_mps',0.0) or 0.0
    sd=obs.get('steer_deg',0.0) or 0.0
    TH+=v*math.tan(math.radians(sd))/L*dt
    X+=v*math.cos(TH)*dt;Y+=v*math.sin(TH)*dt
    h=obs.get('hitch_deg',0.0) or 0.0
    rig=obs.get('rig',{})
    views=obs.get('views',{}) or {}
    for vw in views.values():
        try:
            ox,oy=vw['origin']
        except Exception:
            continue
        for b,d in pts_of(vw.get('walls')):
            if d>10: continue
            br=math.radians(b)
            wx,wy=w2(ox+d*math.cos(br),oy+d*math.sin(br))
            walls[(int(round(wx/0.2)),int(round(wy/0.2)))]=(wx,wy)
        for b,d in pts_of(vw.get('target_corners')):
            if d>12: continue
            br=math.radians(b)
            wx,wy=w2(ox+d*math.cos(br),oy+d*math.sin(br))
            done=False
            for c in clusters:
                if math.hypot(c[0]-wx,c[1]-wy)<0.6:
                    n=c[2];c[0]=(c[0]*n+wx)/(n+1);c[1]=(c[1]*n+wy)/(n+1);c[2]=min(n+1,20);done=True;break
            if not done and len(clusters)<10: clusters.append([wx,wy,1])
    if tick%50==0:
        for k in list(walls.keys()):
            p=walls[k]
            if math.hypot(p[0]-X,p[1]-Y)>18: del walls[k]
    tg=obs.get('target',{}) or {}
    if tg.get('in_sight') and tg.get('dist_m') is not None:
        ex,ey=rig.get('eye',[1.62,0.41])
        b=math.radians(tg['bearing_deg']);d=tg['dist_m']
        p=w2(ex+d*math.cos(b),ey+d*math.sin(b))
        tgt=p if tgt is None else (0.7*tgt[0]+0.3*p[0],0.7*tgt[1]+0.3*p[1])
    tr=rig.get('trailer_rear',[-4.55,0.0])
    R=w2(tr[0],tr[1])
    tdir=TH+math.radians(rig.get('trailer_heading_deg',-h))+math.pi
    look=look_for(tick)
    cnt=obs.get('counters',{})
    touches=cnt.get('touches',0) or 0
    status=obs.get('status','')
    hold=mo.get('hold_s',0) or 0
    if touches>last_touch:
        last_touch=touches
        phase='fwd';fwd_dist=0.0
        print('touch -> fwd h=%.1f'%h)
    if status=='JACKKNIFED' or abs(h)>42:
        if phase!='fwd': print('fold -> fwd h=%.1f'%h)
        phase='fwd';fwd_dist=0.0
    if phase=='fwd':
        fwd_dist+=abs(v)*dt
        if (fwd_dist>1.5 and abs(h)<10) or fwd_dist>4.0:
            phase='rev';stuck_t=0.0
        else:
            return (clip(-1.0*h,-34,34),0.8,look)
    if hold<=0 and abs(v)<0.05 and tick>30:
        stuck_t+=dt
    else:
        stuck_t=0.0
    if stuck_t>2.0:
        stuck_t=0.0;phase='fwd';fwd_dist=0.0;print('stuck -> fwd')
        return (clip(-1.0*h,-34,34),0.8,look)
    hw=(rig.get('trailer_half_width',0.85) or 0.85)+0.15
    best=None;bs=-1e9;bfree=0
    for i in range(-14,15):
        a=math.radians(5*i)
        f=free_dir(R,tdir+a,hw)
        s=min(f,8.0)-0.015*abs(5*i)-0.01*abs(5*i-math.degrees(prev_rel))
        if s>bs: bs=s;best=a;bfree=f
    rel=best;mode='gap';dist_t=None
    if tgt is not None:
        dx=tgt[0]-R[0];dy=tgt[1]-R[1];dist_t=math.hypot(dx,dy)
        at=angn(math.atan2(dy,dx)-tdir)
        ft=free_dir(R,tdir+at,hw-0.1)
        if abs(at)<math.radians(80) and (ft>=dist_t-0.3 or dist_t<4):
            rel=at;mode='tgt'
            good=[c for c in clusters if c[2]>=2]
            if len(good)>=3 and dist_t<9:
                mx=sum(c[0] for c in good)/len(good);my=sum(c[1] for c in good)/len(good)
                sxx=sum((c[0]-mx)**2 for c in good);syy=sum((c[1]-my)**2 for c in good);sxy=sum((c[0]-mx)*(c[1]-my) for c in good)
                th=0.5*math.atan2(2*sxy,sxx-syy)
                ux=math.cos(th);uy=math.sin(th)
                C=tgt if len(good)<4 else (mx,my)
                if (C[0]-R[0])*ux+(C[1]-R[1])*uy<0: ux=-ux;uy=-uy
                al=(R[0]-C[0])*ux+(R[1]-C[1])*uy
                la=min(al+2.5,1.5)
                ax=C[0]+ux*la;ay=C[1]+uy*la
                rel=angn(math.atan2(ay-R[1],ax-R[0])-tdir);mode='bay'
    rel=clip(rel,math.radians(-70),math.radians(70))
    prev_rel=rel
    hd=clip(-1.2*math.degrees(rel),-35,35)
    steer=clip(2.5*(h-hd),-34,34)
    sp=-1.2
    if abs(h)>25 or bfree<2.5: sp=-0.8
    if dist_t is not None and dist_t<3.5: sp=-0.6
    if tick%20==0:
        print('t%.1f %s h%.0f hd%.0f rel%.0f fr%.1f dt%s cl%d w%d'%(obs.get('t',0),mode,h,hd,math.degrees(rel),bfree,('%.1f'%dist_t) if dist_t else '-',len(clusters),len(walls)))
    return (steer,sp,look)

