import math
L=2.75
X=0.0;Y=0.0;TH=0.0
init=False
P=None;U=None
revd=0.0
tick=0
def clip(v,a,b):
    return a if v<a else (b if v>b else v)
def angn(a):
    return (a+math.pi)%(2*math.pi)-math.pi
def w2(px,py):
    c=math.cos(TH);s=math.sin(TH)
    return (X+c*px-s*py, Y+s*px+c*py)
def control(obs):
    global X,Y,TH,init,P,U,revd,tick
    tick+=1
    try:
        dt=obs.get('dt',0.1) or 0.1
        mo=obs.get('motion',{})
        v=mo.get('v_mps',0.0) or 0.0
        sd=obs.get('steer_deg',0.0) or 0.0
        TH+=v*math.tan(math.radians(sd))/L*dt
        X+=v*math.cos(TH)*dt;Y+=v*math.sin(TH)*dt
        h=obs.get('hitch_deg',0.0) or 0.0
        rig=obs.get('rig',{})
        tr=rig.get('trailer_rear',[-4.5,-0.6])
        R=w2(tr[0],tr[1])
        tdir=TH+math.radians(rig.get('trailer_heading_deg',-h))+math.pi
        if not init:
            init=True
            U=(math.cos(tdir),math.sin(tdir))
            n=(-U[1],U[0])
            P=(R[0]+0.25*n[0],R[1]+0.25*n[1])
        if v<0: revd+=-v*dt
        if revd>3.6:
            if tick%10==0: wake('reversed 3.6m, stopping')
            return (0.0,0.0,-23.0)
        al=(R[0]-P[0])*U[0]+(R[1]-P[1])*U[1]
        la=al+2.5
        ax=P[0]+U[0]*la;ay=P[1]+U[1]*la
        rel=angn(math.atan2(ay-R[1],ax-R[0])-tdir)
        rel=clip(rel,math.radians(-15),math.radians(15))
        hd=clip(-1.2*math.degrees(rel),-12,12)
        steer=clip(2.5*(h-hd),-34,34)
        if tick%10==0: print('t%.1f h%.1f hd%.1f rel%.1f revd%.2f'%(obs.get('t',0),h,hd,math.degrees(rel),revd))
        return (steer,-0.6,-23.0)
    except Exception as e:
        print('ERR',e)
        return (0.0,0.0,-23.0)

