import math
X=0.0
mode='fwd'
t0=None
pts={}
corn=[]
tgt=[]
seq=[170,150,125,100,64,35,0,-35,-64,-100,-125,-150,-170]
def P(o,b,d):
    br=math.radians(b)
    return (o[0]+d*math.cos(br),o[1]+d*math.sin(br))
def control(obs):
    global X,mode,t0
    v=obs['motion']['v_mps']; dt=obs.get('dt',0.1) or 0.1
    X+=v*dt
    h=obs['hitch_deg']
    if mode=='fwd':
        if obs['motion']['hold_s']>0: return (0.0,0.8,0)
        if X>2.0: mode='stop'
        return (max(-45,min(45,-0.8*h)),0.8,0)
    if mode=='stop':
        if abs(v)<0.01:
            mode='scan'; t0=obs['t']
        return (obs['steer_deg'],0,0)
    i=int((obs['t']-t0)/0.7)
    if i>=len(seq):
        if mode!='done':
            mode='done'
            r=obs['rig']
            print('RIG hitch',r['hitch'],'rear',r['trailer_rear'],'trhd',r['trailer_heading_deg'],'hitchdeg',h,'prog',obs.get('progress'))
            ks=sorted(pts.keys())
            print('WALLS(x,y veh frame, 0.5m grid):',' '.join('%.1f,%.1f'%(k[0]/2.0,k[1]/2.0) for k in ks))
            print('CORNERS',corn[:8])
            print('TARGET',tgt[-3:])
            try: wake('scan done')
            except Exception: pass
        return (obs['steer_deg'],0,-170)
    views=obs.get('views') or {}
    for name,vw in views.items():
        if not vw: continue
        try:
            o=vw['origin']
            for b,d in vw.get('walls',[]):
                if d>22: continue
                x,y=P(o,b,d)
                pts[(round(x*2),round(y*2))]=1
            for c in (vw.get('target_corners') or []):
                try:
                    x,y=P(o,c[0],c[1]); s=(round(x,1),round(y,1))
                    if s not in corn: corn.append(s)
                except Exception: pass
        except Exception: pass
    tg=obs.get('target') or {}
    if tg.get('in_sight'):
        tgt.append((tg.get('bearing_deg'),tg.get('dist_m')))
    return (obs['steer_deg'],0,seq[i])

