import math
L=2.5; LT=3.6; A=1.3
X=0.0; Y=0.0; TH=0.0
cells={}
mode='rev'
lastp=-10
woke=0
CX=-3.0; CY=11.0; R=9.5
def wrap(a):
    return (a+math.pi)%(2*math.pi)-math.pi
def W(px,py):
    c=math.cos(TH); s=math.sin(TH)
    return X+c*px-s*py, Y+s*px+c*py
def pathpt(s):
    # s = arc length along path
    th=s/R
    if th<=math.pi/2:
        return (CX-R*math.sin(th), CY-R*math.cos(th))
    return (CX-R, CY+(s-R*math.pi/2))
def proj(px,py):
    best=0; bd=1e9
    for i in range(0,300):
        s=i*0.1
        qx,qy=pathpt(s)
        d=(qx-px)**2+(qy-py)**2
        if d<bd: bd=d; best=s
    return best, math.sqrt(bd)
def control(obs):
    global X,Y,TH,mode,lastp,woke
    t=obs.get('t',0.0); dt=obs.get('dt',0.1) or 0.1
    m=obs['motion']; v=m['v_mps']; st=math.radians(obs['steer_deg'])
    X+=v*math.cos(TH)*dt; Y+=v*math.sin(TH)*dt; TH+=v*math.tan(st)/L*dt
    views=obs.get('views') or {}
    for name,vw in views.items():
        if not vw: continue
        try:
            ox,oy=vw['origin']
            for b,d in vw.get('walls',[]):
                if d>12: continue
                br=math.radians(b)
                wx,wy=W(ox+d*math.cos(br),oy+d*math.sin(br))
                cells[(round(wx*4),round(wy*4))]=t
        except Exception:
            pass
    for k in [k for k,tt in cells.items() if t-tt>6.0]: del cells[k]
    rig=obs['rig']
    h=obs['hitch_deg']; phi=math.radians(h)
    rem=(obs.get('progress') or {}).get('remaining',99)
    status=obs.get('status','')
    look=170 if (t%3.0)<2.0 else -64
    rx,ry=rig['trailer_rear']; hx,hy=rig['hitch']
    RX,RY=W(rx,ry); HX,HY=W(hx,hy)
    psi=math.atan2(RY-HY,RX-HX)
    if status=='JACKKNIFED' or abs(h)>55: mode='fix'
    if mode=='fix':
        if abs(h)<15: mode='rev'
        else: return (max(-45,min(45,-1.5*h)),0.8,look)
    if mode=='halt':
        return (obs['steer_deg'],0,look)
    s0,dev=proj(RX,RY)
    tx,ty=pathpt(s0+3.0)
    e=wrap(math.atan2(ty-RY,tx-RX)-psi)
    phr=max(-0.7,min(0.7,-1.3*e))
    dff=math.atan(L*math.sin(phr)/(LT+A*math.cos(phr)))
    sd=math.degrees(dff+2.5*(phi-phr))
    sd=max(-45,min(45,sd))
    sp=-0.5
    if abs(phi-phr)>math.radians(12): sp=-0.3
    # trailer corner clearance
    hw=rig.get('trailer_half_width',1.2)
    ux=hx-rx; uy=hy-ry; n=math.hypot(ux,uy) or 1.0; ux/=n; uy/=n
    nx=-uy; ny=ux
    loc={'tRL':(rx+hw*nx,ry+hw*ny),'tRR':(rx-hw*nx,ry-hw*ny),'tML':(rx+2.3*ux+hw*nx,ry+2.3*uy+hw*ny),'tMR':(rx+2.3*ux-hw*nx,ry+2.3*uy-hw*ny)}
    cl={}
    for nm,(cx,cy) in loc.items():
        wx,wy=W(cx,cy); b=9.0
        for (kx,ky) in cells:
            dd=math.hypot(kx/4.0-wx,ky/4.0-wy)
            if dd<b: b=dd
