    mn=min(cl,key=lambda k:cl[k])
    if t-lastp>3:
        lastp=t
        print('t%.1f rem%.1f hit%.1f phr%.1f e%.1f s%.1f dev%.2f R(%.1f,%.1f) %s' % (t,rem,h,math.degrees(phr),math.degrees(e),s0,dev,RX,RY,dict((k,round(c,2)) for k,c in cl.items())))
    if cl[mn]<0.1 and v<-0.05:
        mode='halt'
        print('HALT',cl,'hit',h,'R',RX,RY)
        try: wake('halt %s %.2f'%(mn,cl[mn]))
        except Exception: pass
        return (obs['steer_deg'],0,look)
    if RY>13 and woke<1:
        woke=1
        try: wake('through first bend, R=(%.1f,%.1f)'%(RX,RY))
        except Exception: pass
    return (sd,sp,look)

