        try: wake('halt %s %.2f'%(mn,cl[mn]))
        except Exception: pass
        return (obs['steer_deg'],0,look)
    if rem<-1.5 and woke<2:
        woke=2
        try: wake('past bay centre')
        except Exception: pass
    return (sd,sp,look)

