import math
X=5.3
Y=1.8
PS=-18.8
phase='fwd'
fd=0.0
D2=-114.0
PTS=[(22.0,9.3),(4.0,-3.0),(-1.5,-8.5)]
T=None
last_touch=None
n=0

def _wake(m):
    try:
        wake(m)
    except Exception:
        pass

def wrap(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a

def W(p):
    c=math.cos(math.radians(PS)); s=math.sin(math.radians(PS))
    return (X+c*p[0]-s*p[1], Y+s*p[0]+c*p[1])

def poly():
    P=PTS[-1]
    if T is not None:
        dx=T[0]-P[0]; dy=T[1]-P[1]; m=math.hypot(dx,dy) or 1.0
        E=(T[0]+15*dx/m, T[1]+15*dy/m)
    else:
        E=(P[0]+70*math.cos(math.radians(D2)), P[1]+70*math.sin(math.radians(D2)))
    return PTS+[E]

def look_pt(A,Ld):
    pl=poly()
    best=None; cum=0.0; segs=[]
    for i in range(len(pl)-1):
        a=pl[i]; b=pl[i+1]
        dx=b[0]-a[0]; dy=b[1]-a[1]; L=math.hypot(dx,dy) or 1e-6
        t=((A[0]-a[0])*dx+(A[1]-a[1])*dy)/(L*L)
        t=max(0.0,min(1.0,t))
        q=(a[0]+t*dx,a[1]+t*dy)
        d=math.hypot(A[0]-q[0],A[1]-q[1])
        if best is None or d<best[0]: best=(d,cum+t*L)
        segs.append((a,dx,dy,L,cum)); cum+=L
    s=best[1]+Ld
    for a,dx,dy,L,c0 in segs:
        if s<=c0+L:
            t=(s-c0)/L
            return (a[0]+t*dx,a[1]+t*dy),best[0]
    a,dx,dy,L,c0=segs[-1]
    return (a[0]+dx,a[1]+dy),best[0]

def lwall(p):
    if p[0]<-2.0: return 9.0
    return (p[0])*math.sin(math.radians(30))-(p[1]-2.0)*math.cos(math.radians(30))

def control(obs):
    global X,Y,PS,phase,fd,T,last_touch,n
    n+=1
    dt=obs.get('dt',0.1)
    v=obs['motion']['v_mps']
    sd=obs.get('steer_deg',0.0)
    PS+=math.degrees(v*math.tan(math.radians(sd))/3.9*dt)
    X+=v*math.cos(math.radians(PS))*dt
    Y+=v*math.sin(math.radians(PS))*dt
    phi=obs['hitch_deg']
    tc=obs['counters']['touches']
    status=obs.get('status')
    look=-41
    if last_touch is None: last_touch=tc
    if tc!=last_touch:
        last_touch=tc; phase='hold'
        _wake('touch phi %.1f X%.1f Y%.1f PS%.1f'%(phi,X,Y,PS))
    if phase=='hold':
        return (sd,0.0,look)
    if phase=='fwd':
        if v>0: fd+=v*dt
        if fd<10.0:
            if n%20==0: print('fwd d%.1f phi%.1f X%.1f Y%.1f PS%.1f'%(fd,phi,X,Y,PS))
            return (18.0,1.3,look)
        phase='rev'
    if phase=='pull':
        if v>0: fd+=v*dt
        if fd<3.0: return (0.0,1.0,look)
        phase='rev'
    if status=='JACKKNIFED' or abs(phi)>66:
        phase='pull'; fd=0.0
        _wake('pull fwd phi %.1f'%phi)
        return (0.0,1.0,look)
    for cpt in [(-1.3,1.28),(-1.3,-1.28)]:
        wc=W(cpt)
        if lwall(wc)<0.4 and v<0:
            phase='hold'
            _wake('truck rear near left rail X%.1f Y%.1f PS%.1f phi%.1f'%(X,Y,PS,phi))
            return (sd,0.0,look)
    rig=obs['rig']
    hx,hy=rig['hitch']; rx,ry=rig['trailer_rear']
    ux,uy=rx-hx,ry-hy; m=math.hypot(ux,uy) or 1.0; ux/=m; uy/=m
    A=W((rx-1.9*ux,ry-1.9*uy)); R=W((rx,ry))
    tht=wrap(PS+math.degrees(math.atan2(uy,ux)))
    tg=obs.get('target') or {}
    P=PTS[-1]
    if tg.get('in_sight') and tg.get('bearing_deg') is not None:
        ex,ey=rig['eye']; b=math.radians(tg['bearing_deg']); d=tg['dist_m']
        tw=W((ex+d*math.cos(b),ey+d*math.sin(b)))
        ang=math.degrees(math.atan2(tw[1]-P[1],tw[0]-P[0]))
        if abs(wrap(ang-D2))<25 and math.hypot(tw[0]-P[0],tw[1]-P[1])>10:
            T=tw if T is None else (0.9*T[0]+0.1*tw[0],0.9*T[1]+0.1*tw[1])
    LP,cte=look_pt(A,8.0)
    thd=math.degrees(math.atan2(LP[1]-A[1],LP[0]-A[0]))
    corr=0.0; lmin=9.0; rmin=9.0
    cam=(obs.get('views') or {}).get('camera')
    if cam:
        ox,oy=cam['origin']
        dxx=math.cos(math.radians(tht)); dyy=math.sin(math.radians(tht))
        for b,d in cam.get('walls',[]):
            br=math.radians(b)
            wx,wy=W((ox+d*math.cos(br),oy+d*math.sin(br)))
            px=wx-R[0]; py=wy-R[1]
            al=px*dxx+py*dyy; la=dxx*py-dyy*px
