    phid=-math.degrees(math.atan(2.5*math.sin(math.radians(e))))
    phid=max(-40.0,min(40.0,phid))
    st=math.degrees(math.atan(0.4*math.sin(math.radians(phid))))+2.5*(phi-phid)
    st=max(-42.0,min(42.0,st))
    sp=-0.9
    if abs(phi-phid)>15: sp=-0.6
    if T is not None and math.hypot(T[0]-A[0],T[1]-A[1])<12: sp=-0.6
    if n%20==0:
        print('t%.0f X%.1f Y%.1f PS%.1f A(%.1f,%.1f) th%.1f thd%.1f phi%.1f phid%.1f st%.1f cte%.1f l%.1f r%.1f T%s'%(obs['t'],X,Y,PS,A[0],A[1],tht,thd,phi,phid,st,cte,lmin,rmin,('(%.1f,%.1f)'%T) if T else '-'))
    return (st,sp,look)

