            if along<-1.5:
                phase='hold'; wk('passed target along %.1f lat %.1f phi %.1f'%(along,lat,phi))
                return (sd,0.0,-41)
    e_last=e
    rep=0.0
    for al,la in inner:
        if -3<al<6 and la<2.0: rep=min(rep,-(2.0-la)*10)
    for al,la in outer:
        if -3<al<6 and -la<2.3: rep=max(rep,(2.3+la)*10)
    ed=math.degrees(e)+rep
    ed=max(-35.0,min(35.0,ed))
    phid=-math.degrees(math.atan(2.0*math.sin(math.radians(ed))))
    phid=max(-45.0,min(45.0,phid))
    st=math.degrees(math.atan(0.4*math.sin(math.radians(phid))))+2.5*(phi-phid)
    st=max(-42.0,min(42.0,st))
    sp=-0.7
    if abs(phi-phid)>15 or near: sp=-0.5
    if n%20==0:
        print('t%.0f rd%.1f phi%.1f phid%.1f ed%.1f w%.1f rep%.1f st%.1f ni%d no%d dmin%.2f %s T%s al%s'%(t,revd,phi,phid,ed,math.degrees(w),rep,st,len(inner),len(outer),dmin,dwhere,('(%.1f,%.1f)'%T) if T else '-',('%.1f'%along) if along is not None else '-'))
    return (st,sp,look)

